const input = $json.body ?? $json;
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };

const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const packageStatus = String(input.offer_package_status ?? input.controller_status ?? "").toLowerCase();
const channel = String(input.preferred_channel ?? input.channel ?? "sms").toLowerCase();
const recipient = String(input.recipient ?? input.seller_phone ?? input.seller_email ?? "").trim();
const message = String(input.seller_message ?? input.message ?? "").trim();
const openingOffer = num(input.opening_offer);
const adjustedMao = num(input.adjusted_mao ?? input.dynamic_mao);
const sellerReviewRequired = input.seller_review_required === true;
const sellerAuthorized = input.seller_authorized === true || input.human_authorized === true;
const dnc = input.dnc === true || input.do_not_contact === true;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];

const identityReady = Boolean(dealId && leadId && propertyId);
const channelReady = channel === "sms" || channel === "email";
const recipientReady = Boolean(recipient);
const messageReady = Boolean(message);
const priceReady = openingOffer !== null && openingOffer >= 0 && adjustedMao !== null && openingOffer <= adjustedMao;
const authorizationReady = !sellerReviewRequired || sellerAuthorized;
const blocked = dnc || blockers.length > 0;

let status = "dispatch_ready";
let nextWorkflow = "WF-336";
let reason = "Offer package is valid, authorized, and ready for provider dispatch.";

if (!identityReady || !channelReady || !recipientReady || !messageReady || !priceReady || !authorizationReady) {
  status = sellerReviewRequired && !sellerAuthorized ? "awaiting_human_authorization" : "incomplete";
  nextWorkflow = sellerReviewRequired && !sellerAuthorized ? "WF-126" : "WF-334";
  reason = sellerReviewRequired && !sellerAuthorized
    ? "Seller outreach requires explicit human authorization before dispatch."
    : "Offer dispatch identity, channel, recipient, message, price, or authorization inputs are incomplete.";
} else if (blocked) {
  status = "blocked";
  nextWorkflow = "WF-126";
  reason = "DNC or active blockers prevent seller outreach.";
}

const dispatchId = input.dispatch_id ?? \`wf335-\${dealId ?? "unknown"}-\${propertyId ?? "unknown"}-\${Date.now()}\`;
const idempotencyKey = input.idempotency_key ?? \`wf-335:\${dealId ?? "unknown"}:\${propertyId ?? "unknown"}:\${openingOffer ?? "unknown"}:\${channel}\`;

return [{
  json: {
    ...input,
    workflow_id: "WF-335",
    controller_status: status,
    dispatch_status: status,
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    channel: channel === "email" ? "email" : "sms",
    recipient,
    message,
    opening_offer: openingOffer,
    adjusted_mao: adjustedMao,
    seller_review_required: sellerReviewRequired,
    seller_authorized: sellerAuthorized,
    dnc,
    dispatch_id: dispatchId,
    idempotency_key: idempotencyKey,
    delivery_receipt_required: true,
    provider_execution: "runtime_provider_adapter",
    provider_credentials: "runtime_only_not_committed",
    next_workflow: nextWorkflow,
    reason,
    requires_human_review: status === "awaiting_human_authorization" || status === "blocked"
  }
}];
